with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('se stort på', 'phrase', '4420fa44-37db-5b37-83e9-793139371250', 1, 'verb', null, 'to ignore, to disregard (something)', 'Hun ser stort på reglerne og gør, hvad hun vil.', 'She ignores the rules and does what she wants.'), ('stå over', 'phrase', '44b4ce38-6967-59bd-944d-b6aa2341866d', 1, 'verb', null, 'to skip (one''s turn)', 'Jeg står over denne gang.', 'I''m sitting out this time.'), ('stå over for', 'phrase', '0d59f120-0b3c-530a-b859-0f9dd65fa6c1', 1, 'verb', null, 'to face (a problem, choice)', 'Vi står over for en stor udfordring.', 'We are facing a major challenge.'), ('holde sig til', 'phrase', '0e76631b-afc4-5be4-bd55-8a2faef4d4d7', 1, 'verb', null, 'to stick to (something)', 'Jeg holder mig til de regler, vi har aftalt.', 'I am sticking to the rules we have agreed.'), ('gå frem', 'phrase', '85a09b7a-7cd0-58ac-8246-160b43c33c8d', 1, 'verb', null, 'to advance', 'Projektet gik frem hurtigere end forventet.', 'The project progressed faster than expected.'), ('gå frem', 'phrase', '9a0e8ddb-496d-5271-9f86-0d04348e9093', 2, 'verb', null, 'to increase (of numbers)', 'Salget gik frem med ti procent sidste år.', 'Sales increased by ten percent last year.'), ('køre ind', 'phrase', 'ed78d4d2-d8f3-5f2f-997c-841b2f16f797', 1, 'verb', null, 'to drive in', 'Bilen kører ind i garagen.', 'The car drives into the garage.'), ('slå til', 'phrase', '3753aaea-834c-56d1-9d38-74df8343097a', 1, 'verb', null, 'to be sufficient', 'Pengene slog til hele måneden.', 'The money was enough for the whole month.'), ('slå til', 'phrase', 'b8027f0a-8ca5-5ce2-8c36-7dcc4870a244', 2, 'verb', null, 'to accept (an offer)', 'Hun slog til med det samme.', 'She accepted immediately.'), ('sætte pris på', 'phrase', '22820690-b849-5215-bb93-e546aa62e104', 1, 'verb', null, 'to appreciate', 'Jeg sætter pris på din hjælp.', 'I appreciate your help.'), ('samle sig', 'phrase', '5410829f-568b-5cbb-8b9c-97f35c6b95ce', 1, 'verb', null, 'to pull oneself together', 'Du må samle dig og gøre arbejdet færdigt.', 'You must gather yourself and finish the job.'), ('stige op', 'phrase', '79813b72-d68a-5d66-8900-81c6288e7ce6', 1, 'verb', null, 'to ascend', 'Han steg op ad trappen til anden sal.', 'He ascended the stairs to the second floor.'), ('åbne øjnene', 'phrase', '472efb4e-541f-5e80-8d84-4b27ad80eec5', 1, 'verb', null, 'to open someone''s eyes (to the truth)', 'Hun åbnede øjnene på mig for problemet.', 'She opened my eyes to the problem.'), ('komme igennem', 'phrase', '2dce3a6d-a959-5bb1-bfbd-0b085ed81a5f', 1, 'verb', null, 'to get through (a difficulty)', 'Det var en svær tid, men vi kom igennem den sammen.', 'It was a difficult time, but we got through it together.'), ('komme igennem', 'phrase', '548f85b0-84fc-5c6f-8d3f-5c03d17c87ca', 2, 'verb', null, 'to pass (an exam)', 'Jeg håber, at jeg kommer igennem eksamen i morgen.', 'I hope I get through the exam tomorrow.'), ('gå fra hinanden', 'phrase', 'e2450623-a12f-5f7e-a814-6e022e8dda4b', 1, 'verb', null, 'to break up (of a couple)', 'De gik fra hinanden efter fem år sammen.', 'They broke up after five years together.'), ('skrive hjem', 'phrase', '68b70276-c8b4-56c5-a5fd-2d2c21f2940d', 1, 'verb', null, 'to write home (send news)', 'Hun skrev hjem om sin nye lejlighed.', 'She wrote home about her new apartment.'), ('søge efter', 'phrase', '626c5867-14e4-5479-b760-d2d8708f639c', 1, 'verb', null, 'to search for', 'Jeg søger efter mine nøgler overalt.', 'I search for my keys everywhere.'), ('løbe med', 'phrase', '3c68c811-7db6-585a-b0d2-35fdae631d31', 1, 'verb', null, 'to run off with', 'Tyven løb med min taske.', 'The thief ran off with my bag.'), ('løbe rundt', 'phrase', '798120f4-b7d3-5bfb-8f69-556f7218291c', 1, 'verb', null, 'to run around', 'Børnene løber rundt i haven hele dagen.', 'The children run around in the garden all day.'), ('kigge efter', 'phrase', '82593d9f-85c9-575c-980d-cd7e72e52362', 1, 'verb', null, 'to look for', 'Jeg kigger efter mine nøgler overalt.', 'I look for my keys everywhere.'), ('stoppe op', 'phrase', '4c62629b-f258-5dcd-9cb3-416de7e31048', 1, 'verb', null, 'to stop (while moving)', 'Bilen stopper op foran lyskrydset.', 'The car stops in front of the traffic lights.'), ('pege på', 'phrase', 'b80b422e-8712-533b-bb37-78de409755f6', 1, 'verb', null, 'to point at', 'Hun peger på tavlen med en lang pind.', 'She points to the board with a long stick.'), ('gå om bord', 'phrase', '0927ec6f-1ee0-5651-87f5-7bece5ab2808', 1, 'verb', null, 'to board (a ship or plane)', 'Passagererne gik om bord i flyet en time før afgang.', 'The passengers boarded the plane an hour before departure.'), ('spise ude', 'phrase', '32a7fcd0-7c3d-5032-8209-8a91a17b36b7', 1, 'verb', null, 'to eat out', 'Vi spiser ude hver fredag.', 'We eat out every Friday.'), ('kæmpe mod', 'phrase', 'd2428959-7179-52ce-9d6b-1b58ae0af966', 1, 'verb', null, 'to fight against', 'De kæmper mod uretfærdighed hver dag.', 'They fight against injustice every day.'), ('byde på', 'phrase', '02802807-8ada-500d-b466-2dec94507bfe', 1, 'verb', null, 'to offer (to guests)', 'Værten bød på kaffe og kage.', 'The host offered coffee and cake.'), ('byde på', 'phrase', 'fda70ed0-9648-5b87-8ddf-2ebc7d7c65ac', 2, 'verb', null, 'to promise (indicate)', 'Den mørke himmel byder på regn.', 'The dark sky promises rain.'), ('glæde sig over', 'phrase', 'e5d7c04d-2931-5da1-8056-6b0f4b5bf7ed', 1, 'verb', null, 'to be happy about', 'Jeg glæder mig over det gode vejr i dag.', 'I am happy about the good weather today.'), ('synge for', 'phrase', '6905e9ed-9e54-5f9a-84ce-46910ab34192', 1, 'verb', null, 'to sing for (someone)', 'Hun sang for sin familie til fødselsdagen.', 'She sang for her family at the birthday party.'), ('dække bord', 'phrase', 'a9e79694-91ad-5998-b7b1-22814e425da1', 1, 'verb', null, 'to set the table', 'Hun dækker bord med tallerkener og glas.', 'She sets the table with plates and glasses.'), ('gemme sig under', 'phrase', '3784c77f-f8e3-5696-b6b2-ae1125272fa6', 1, 'verb', null, 'to hide under', 'Katten gemmer sig under bordet.', 'The cat hides under the table.'), ('forberede sig på', 'phrase', '0e510ec2-74a2-5036-9895-47009a3b7d5a', 1, 'verb', null, 'to prepare (oneself) for', 'Vi forbereder os på en lang vinter.', 'We are preparing for a long winter.'), ('gå for vidt', 'phrase', 'e95e8164-5042-58df-a73f-0c818238cfd0', 1, 'verb', null, 'to go too far', 'Jeg synes, du gik for vidt med den kommentar.', 'I think you went too far with that comment.'), ('drage i krig', 'phrase', 'a789e11e-1a30-5e03-ac4b-2632f15cde17', 1, 'verb', null, 'to go to war', 'Kongen drog i krig mod nabolandet.', 'The king went to war against the neighboring country.'), ('have sex', 'phrase', 'b59b99ce-3fc0-56d5-96af-a59ee612864b', 1, 'verb', null, 'to have sex', 'De har sex hver aften.', 'They have sex every evening.'), ('have en skrue løs', 'phrase', '2ec55c31-8dd7-5639-910e-be8d51617282', 1, 'verb', null, 'to have a screw loose (be slightly crazy)', 'Jeg tror, han har en skrue løs, for han taler hele tiden med sig selv.', 'I think he has a screw loose, because he talks to himself all the time.'), ('sætte ild til', 'phrase', '7a979f67-6303-5389-a067-13b5633ea9f1', 1, 'verb', null, 'to set fire to', 'Nogen har sat ild til skuret bag huset.', 'Someone has set fire to the shed behind the house.'), ('hoppe på', 'phrase', '123b3745-f645-569c-93a6-dec543495f8e', 1, 'verb', null, 'to jump at (an offer)', 'Han hoppede på tilbuddet med det samme.', 'He jumped at the offer immediately.'), ('forsyne sig', 'phrase', '38d42a0e-6f50-5c9c-ab19-6a3484e6a969', 1, 'verb', null, 'to help oneself (to food)', 'Gæsterne kan forsyne sig fra buffeten hele aftenen.', 'Guests can help themselves from the buffet throughout the evening.'), ('skynde sig hjem', 'phrase', '995c6467-bfd8-5b43-9849-3ad28025cf15', 1, 'verb', null, 'to hurry home', 'Børnene skynder sig hjem efter skole.', 'The children rush home after school.'), ('have for vane at', 'phrase', '3ba05aec-f200-50ca-a69d-243e0bb6c343', 1, 'verb', null, 'to be in the habit of (doing something)', 'Jeg har for vane at drikke kaffe om morgenen.', 'I have a habit of drinking coffee in the morning.'), ('pønse på', 'phrase', '4cfc9386-77a9-5d33-b47f-9c9362a0bff9', 1, 'verb', null, 'to plot (something bad)', 'De to drenge pønser på en hemmelig plan.', 'The two boys are hatching a secret plan.'), ('bugte sig', 'phrase', 'd7444315-60bb-5428-9494-b3724b6a1bd7', 1, 'verb', null, 'to wind (road, river)', 'Stien bugter sig gennem skoven.', 'The path meanders through the forest.'), ('have hjemve', 'phrase', '05762bca-ac20-54d0-95cc-91be2121c13f', 1, 'verb', null, 'to be homesick', 'Hun har hjemve, når hun er på ferie.', 'She is homesick when she is on holiday.'), ('gå med til', 'phrase', '40cc22a2-15af-588d-9936-21de34258d30', 1, 'verb', null, 'to agree (to something)', 'Hun gik med til at hjælpe os i weekenden.', 'She agreed to help us over the weekend.'), ('løbe fra', 'phrase', 'f4bae7fe-448e-5256-bb35-1a35b9c7f1ea', 1, 'verb', null, 'to run away from', 'Hunden løb fra sin ejer i parken.', 'The dog ran away from its owner in the park.'), ('løbe fra', 'phrase', '2d3d3830-9be4-5816-b463-76c6dbec4569', 2, 'verb', null, 'to back out of (a promise)', 'Han løb fra aftalen i sidste øjeblik.', 'He backed out of the deal at the last minute.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0006' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
